import {channel,histogram,parseKernel,prepareKernel} from './core.mjs';
const $=id=>document.getElementById(id);let source=null,filtered=null,faces=[],revision=0,job=0,modelPromise=null,faceBusy=false;
const worker=new Worker('./filter-worker.mjs',{type:'module'});
const presets={gaussian:{k:'1 2 1\n2 4 2\n1 2 1',n:true,b:0},identity:{k:'0 0 0\n0 1 0\n0 0 0',n:false,b:0},sharpen:{k:'0 -1 0\n-1 5 -1\n0 -1 0',n:false,b:0},emboss:{k:'-2 -1 0\n-1 1 1\n0 1 2',n:false,b:128},edge:{k:'0 -1 0\n-1 4 -1\n0 -1 0',n:false,b:0},box5:{k:Array(5).fill('1 1 1 1 1').join('\n'),n:true,b:0}};
function status(text,error=false){$('status').textContent=text;$('status').dataset.error=error;}
function draw(id,data){const c=$(id);c.width=source.width;c.height=source.height;c.getContext('2d').putImageData(new ImageData(new Uint8ClampedArray(data),c.width,c.height),0,0);}
function resetResults(){filtered=null;faces=[];job++;$('applyFilter').disabled=false;$('applyFilter').textContent='套用濾波 ↗';$('downloadFilter').disabled=$('downloadFace').disabled=$('downloadJson').disabled=true;$('psnr').textContent=$('mse').textContent=$('filterTime').textContent='—';$('faceCount').textContent=$('faceTime').textContent='—';$('faceResults').innerHTML='<tr><td colspan="4">尚未執行偵測</td></tr>';$('filterCaption').textContent='AFTER / 尚未套用';$('kernelError').hidden=true;}
async function loadBlob(blob,name){if(blob.size>20*1024*1024)throw Error('檔案超過 20 MB，請選擇較小的圖片。');const url=URL.createObjectURL(blob);try{const img=new Image();img.src=url;await img.decode();if(!img.naturalWidth||!img.naturalHeight||img.naturalWidth*img.naturalHeight>50e6)throw Error('圖片超過 5,000 萬像素或尺寸無效。');const scale=Math.min(1,1600/Math.max(img.naturalWidth,img.naturalHeight)),w=Math.max(1,Math.round(img.naturalWidth*scale)),h=Math.max(1,Math.round(img.naturalHeight*scale));const c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(img,0,0,w,h);revision++;resetResults();source={data:c.getContext('2d').getImageData(0,0,w,h).data,width:w,height:h,name,originalWidth:img.naturalWidth,originalHeight:img.naturalHeight,bytes:blob.size};const items=[['檔案',name],['原始尺寸',`${img.naturalWidth} × ${img.naturalHeight}`],['運算尺寸',`${w} × ${h}`],['解碼色彩','RGBA / 8 bit × 4'],['檔案大小',`${(blob.size/1024).toFixed(1)} KB`]];$('metadata').replaceChildren(...items.map(([a,b])=>{const d=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=a;dd.textContent=b;d.append(dt,dd);return d;}));draw('originalCanvas',source.data);draw('filteredCanvas',source.data);draw('faceCanvas',source.data);renderChannel();status(`${name} 已載入${scale<1?'；已等比例縮小至長邊 1600 px':''}。`);}finally{URL.revokeObjectURL(url);}}
async function safeLoad(blob,name){try{await loadBlob(blob,name);}catch(e){status('無法載入：'+e.message,true);}}
function renderChannel(){if(!source)return;const mode=$('channel').value;draw('colorCanvas',channel(source.data,mode));$('channelTag').textContent=mode==='original'?'ORIGINAL':mode+' CHANNEL';$('histLegend').textContent=mode==='original'?'R / G / B':mode+' / 灰階分布';$('channelNote').textContent='YUV'.includes(mode)?'Y = 0.299R + 0.587G + 0.114B；U = 0.492(B−Y)+128；V = 0.877(R−Y)+128。取整並裁切至 0–255，無色度次取樣。':'單一通道以灰階強度呈現；各 bin 精確統計像素數，透明像素亦依其 RGB 值計入。';renderHistogram(histogram(source.data,mode));}
function renderHistogram(hs){const c=$('histogram'),ctx=c.getContext('2d'),w=c.width,h=c.height,L=72,R=18,T=25,B=43,pw=w-L-R,ph=h-T-B,max=Math.max(1,...hs.map(a=>Math.max(...a)));ctx.clearRect(0,0,w,h);ctx.font='11px Segoe UI, Microsoft JhengHei';ctx.fillStyle='#738078';ctx.textAlign='right';for(let i=0;i<=4;i++){const y=T+ph*i/4;ctx.strokeStyle='#e6eade';ctx.beginPath();ctx.moveTo(L,y);ctx.lineTo(w-R,y);ctx.stroke();ctx.fillText(Math.round(max*(1-i/4)).toLocaleString(),L-10,y+4);}ctx.fillText('像素數量',L-10,12);hs.forEach((a,j)=>{ctx.beginPath();a.forEach((n,i)=>{const x=L+i/255*pw,y=T+ph-n/max*ph;i?ctx.lineTo(x,y):ctx.moveTo(x,y);});ctx.strokeStyle=hs.length===3?['#c86a5c','#65995a','#5b86c4'][j]:'#356a50';ctx.lineWidth=1.7;ctx.stroke();});ctx.textAlign='center';for(const v of [0,64,128,192,255])ctx.fillText(v,L+v/255*pw,h-24);ctx.fillText('像素強度（0–255）',L+pw/2,h-5);}
function switchTab(name){document.querySelectorAll('.tab-panel').forEach(p=>p.hidden=p.id!==name);document.querySelectorAll('[data-tab]').forEach(b=>{const active=b.dataset.tab===name;b.classList.toggle('active',active);b.setAttribute('aria-selected',active);});}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));$('channel').onchange=renderChannel;
$('file').onchange=e=>{const f=e.target.files[0];if(f){if(!/\.(png|jpe?g|bmp)$/i.test(f.name)){status('請選擇 PNG、JPG/JPEG 或 BMP 檔案。',true);return;}safeLoad(f,f.name);}e.target.value='';};
for(const event of ['dragenter','dragover'])$('drop').addEventListener(event,e=>{e.preventDefault();$('drop').classList.add('dragover');});for(const event of ['dragleave','drop'])$('drop').addEventListener(event,e=>{e.preventDefault();$('drop').classList.remove('dragover');});$('drop').addEventListener('drop',e=>{const f=e.dataTransfer.files[0];if(f&&/\.(png|jpe?g|bmp)$/i.test(f.name))safeLoad(f,f.name);else status('請拖入 PNG、JPG/JPEG 或 BMP 圖片。',true);});
async function sampleColor(){const c=document.createElement('canvas');c.width=960;c.height=540;const x=c.getContext('2d');x.fillStyle='#e9e5da';x.fillRect(0,0,960,540);const colors=['#db5f4f','#e7aa47','#e2d972','#78a56b','#5e9d9a','#567baa','#9b76a1'];colors.forEach((v,i)=>{x.fillStyle=v;x.fillRect(48+i*124,45,124,270);});const grad=x.createLinearGradient(48,0,912,0);grad.addColorStop(0,'#000');grad.addColorStop(1,'#fff');x.fillStyle=grad;x.fillRect(48,345,864,64);x.fillStyle='#263e30';x.font='bold 26px sans-serif';x.fillText('PIXEL LAB  /  COLOR & LIGHT',48,475);x.strokeStyle='#263e30';x.lineWidth=3;for(let i=0;i<14;i++){x.beginPath();x.moveTo(590+i*23,440);x.lineTo(590+i*23,493);x.stroke();}await new Promise(resolve=>c.toBlob(async b=>{await safeLoad(b,'色彩測試圖.png');resolve();}));}
$('sampleColor').onclick=sampleColor;$('sampleFace').onclick=async()=>{try{const r=await fetch('samples/group.jpg');if(!r.ok)throw Error('範例暫時無法載入，請使用自己的影像。');await loadBlob(await r.blob(),'多人臉範例.jpg');switchTab('face');}catch(e){status(e.message,true);}};
$('preset').onchange=()=>{const p=presets[$('preset').value];if(p){$('kernel').value=p.k;$('normalize').checked=p.n;$('bias').value=p.b;}};$('kernel').oninput=()=>{$('preset').value='custom';};
$('applyFilter').onclick=()=>{try{if(!source)throw Error('請先載入影像。');const kernel=parseKernel($('kernel').value),options={normalize:$('normalize').checked,bias:Number($('bias').value),border:$('border').value};prepareKernel(kernel,options.normalize);if($('bias').value.trim()===''||!Number.isFinite(options.bias)||Math.abs(options.bias)>255)throw Error('偏移量必須介於 -255 與 255。');$('kernelError').hidden=true;$('applyFilter').disabled=true;$('applyFilter').textContent='運算中…';const id=++job,start=performance.now(),rev=revision;worker.onmessage=({data:m})=>{if(m.id!==job||rev!==revision)return;$('applyFilter').disabled=false;$('applyFilter').textContent='套用濾波 ↗';if(m.error){$('kernelError').hidden=false;$('kernelError').textContent=m.error;return;}filtered=m.result;draw('filteredCanvas',filtered);$('psnr').textContent=Number.isFinite(m.metrics.psnr)?`${m.metrics.psnr.toFixed(3)} dB`:'∞ dB';$('mse').textContent=m.metrics.mse.toFixed(4);$('filterTime').textContent=(performance.now()-start).toFixed(1)+' ms';$('filterCaption').textContent=`AFTER / ${kernel.length}×${kernel.length} 卷積`;$('downloadFilter').disabled=false;status('濾波完成。PSNR 比較原圖與取整裁切後的 RGB 結果。');};worker.postMessage({id,data:source.data,width:source.width,height:source.height,kernel,options});}catch(e){$('kernelError').hidden=false;$('kernelError').textContent=e.message;status('請修正濾波參數。',true);}};
worker.onerror=()=>{$('applyFilter').disabled=false;$('applyFilter').textContent='套用濾波 ↗';status('濾波工作程序失敗，請重新載入頁面。',true);};
$('threshold').oninput=()=>{$('thresholdValue').textContent=Number($('threshold').value).toFixed(2);};
async function ensureModel(){if(!modelPromise){$('modelState').textContent='載入模型中…';modelPromise=(async()=>{if(!window.faceapi)throw Error('人臉函式庫未載入，請重新整理。');await faceapi.tf.setBackend('cpu');await faceapi.tf.ready();await faceapi.nets.tinyFaceDetector.loadFromUri('./models');$('modelState').textContent='模型就緒 / CPU';})().catch(e=>{modelPromise=null;$('modelState').textContent='模型載入失敗';throw e;});}return modelPromise;}
$('detect').onclick=async()=>{if(faceBusy)return;if(!source)return status('請先載入影像。',true);const rev=revision,threshold=Number($('threshold').value),inputSize=Number($('inputSize').value);faceBusy=true;$('detect').disabled=true;$('detect').textContent='偵測中…';try{await ensureModel();if(rev!==revision)return;const input=document.createElement('canvas');input.width=source.width;input.height=source.height;input.getContext('2d').putImageData(new ImageData(new Uint8ClampedArray(source.data),source.width,source.height),0,0);const start=performance.now();const detections=await faceapi.detectAllFaces(input,new faceapi.TinyFaceDetectorOptions({inputSize,scoreThreshold:threshold}));const ms=performance.now()-start;if(rev!==revision)return;faces=detections.map((d,i)=>({id:i+1,score:d.score,x:d.box.x,y:d.box.y,width:d.box.width,height:d.box.height}));draw('faceCanvas',source.data);const ctx=$('faceCanvas').getContext('2d'),lw=Math.max(2,source.width/300),font=Math.max(15,source.width/55);ctx.lineWidth=lw;ctx.font=`bold ${font}px sans-serif`;faces.forEach(d=>{ctx.strokeStyle='#d9f763';ctx.strokeRect(d.x,d.y,d.width,d.height);const label=`#${d.id} ${(d.score*100).toFixed(1)}%`,tw=ctx.measureText(label).width+12,top=Math.max(0,d.y-font-12),left=Math.max(0,Math.min(source.width-tw,d.x));ctx.fillStyle='#d9f763';ctx.fillRect(left,top,tw,font+10);ctx.fillStyle='#173a2b';ctx.fillText(label,left+6,top+font+1);});$('faceCount').textContent=faces.length+' 張';$('faceTime').textContent=ms.toFixed(1)+' ms';$('faceResults').replaceChildren(...faces.map(d=>{const tr=document.createElement('tr');[d.id,(d.score*100).toFixed(2)+'%',`${d.x.toFixed(1)} / ${d.y.toFixed(1)}`,`${d.width.toFixed(1)} / ${d.height.toFixed(1)}`].forEach(v=>{const td=document.createElement('td');td.textContent=v;tr.append(td);});return tr;}));if(!faces.length)$('faceResults').innerHTML='<tr><td colspan="4">未偵測到人臉；可降低門檻或更換圖片。</td></tr>';$('downloadFace').disabled=$('downloadJson').disabled=false;status(`偵測完成：${faces.length} 張人臉，門檻 ${threshold.toFixed(2)}，輸入 ${inputSize}。`);}catch(e){status('偵測失敗：'+e.message,true);}finally{faceBusy=false;$('detect').disabled=false;$('detect').textContent='開始人臉偵測 ↗';}};
function download(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function png(id,name){$(id).toBlob(b=>{if(b)download(b,name);});}
$('downloadChannel').onclick=()=>png('colorCanvas',`pixel-lab-${$('channel').value}.png`);$('downloadFilter').onclick=()=>png('filteredCanvas','pixel-lab-filtered.png');$('downloadFace').onclick=()=>png('faceCanvas','pixel-lab-faces.png');$('downloadJson').onclick=()=>download(new Blob([JSON.stringify({image:source.name,width:source.width,height:source.height,model:'TinyFaceDetector / face-api.js 0.22.2',faces},null,2)],{type:'application/json'}),'pixel-lab-detections.json');
$('helpBtn').onclick=()=>$('help').showModal();$('closeHelp').onclick=()=>$('help').close();$('clearBtn').onclick=async()=>{$('channel').value='original';$('preset').value='gaussian';$('preset').onchange();await sampleColor();};
await sampleColor();
